{"task": "Find logs with service names that don't follow the svc-<name>-<number> pattern", "sql": "SELECT DISTINCT service FROM logs WHERE NOT regexp_like(service, '^svc-[a-z]+-[0-9]+$')"}
{"task": "Count log entries by service name that matches the expected naming convention", "sql": "SELECT service, COUNT(*) as log_count FROM logs WHERE regexp_like(service, '^svc-[a-z]+-[0-9]+$') GROUP BY service"}
{"task": "Identify services with unusual naming patterns in error level logs", "sql": "SELECT service, COUNT(*) as error_count FROM logs WHERE level = 'ERROR' AND NOT regexp_like(service, '^svc-[a-z]+-[0-9]+$') GROUP BY service"}
{"task": "Find event paths that contain user IDs but don't match expected format", "sql": "SELECT path FROM events WHERE regexp_like(path, '/users/[0-9]+/') AND NOT regexp_like(path, '/users/[0-9]+/profile$')"}
{"task": "List services with numeric suffixes in log messages using regex pattern matching", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, 'svc-[a-z]+-[0-9]+')"}
{"task": "Count events per user ID format that matches expected patterns", "sql": "SELECT COUNT(*) as valid_events FROM events WHERE regexp_like(path, '/users/[0-9]+/.*')"}
{"task": "Find logs where service name has incorrect capitalization", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(service, '^[a-z]+-[a-z]+-[0-9]+$') AND NOT regexp_like(service, '^svc-[a-z]+-[0-9]+$')"}
{"task": "Identify service names that have valid format but unusual suffixes", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(service, '^svc-[a-z]+-[0-9]+$') AND regexp_like(service, 'svc-.+-[0-9]{3}$')"}
{"task": "Check for events with path patterns matching API endpoint conventions", "sql": "SELECT user_id, path FROM events WHERE regexp_like(path, '/api/v[0-9]+/.*')"}
{"task": "Find logs where service name matches pattern but message contains errors", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(service, '^svc-[a-z]+-[0-9]+$') AND regexp_like(message, 'error|exception', 'i')"}

